1	package com.example.starter.epidemic.service;
2	
3	import com.example.starter.epidemic.api.ActionResponse;
4	import com.example.starter.epidemic.api.ArchiveRequest;
5	import com.example.starter.epidemic.api.AuditTrailResponse;
6	import com.example.starter.epidemic.api.CardResponse;
7	import com.example.starter.epidemic.api.CardVersionResponse;
8	import com.example.starter.epidemic.api.CorrectCardRequest;
9	import com.example.starter.epidemic.api.ReviewRequest;
10	import com.example.starter.epidemic.api.SpecialConfirmRequest;
11	import com.example.starter.epidemic.api.SpecialCorrectRequest;
12	import com.example.starter.epidemic.api.SpecialCorrectionResponse;
13	import com.example.starter.epidemic.api.SubmitCardRequest;
14	import com.example.starter.epidemic.api.WithdrawRequest;
15	import com.example.starter.epidemic.domain.AuditAction;
16	import com.example.starter.epidemic.domain.AuditTrailPo;
17	import com.example.starter.epidemic.domain.CardPo;
18	import com.example.starter.epidemic.domain.CardStatus;
19	import com.example.starter.epidemic.domain.CardVersionPo;
20	import com.example.starter.epidemic.domain.DiseaseCategory;
21	import com.example.starter.epidemic.domain.DiseasePo;
22	import com.example.starter.epidemic.domain.IdempotencyPo;
23	import com.example.starter.epidemic.domain.SpecialCorrectionPo;
24	import com.example.starter.epidemic.domain.SpecialStatus;
25	import com.example.starter.epidemic.repository.CardRepository;
26	import org.springframework.dao.DuplicateKeyException;
27	import org.springframework.stereotype.Service;
28	import org.springframework.transaction.annotation.Transactional;
29	
30	import java.nio.charset.StandardCharsets;
31	import java.security.MessageDigest;
32	import java.security.NoSuchAlgorithmException;
33	import java.time.Duration;
34	import java.time.Instant;
35	import java.time.LocalDate;
36	import java.util.HexFormat;
37	import java.util.List;
38	import java.util.UUID;
39	
40	/**
41	 * 传染病报告卡业务服务：初报/审核/订正/撤回/终审归档/特殊订正。
42	 *
43	 * <p>关键规则：</p>
44	 * <ul>
45	 *   <li>时限：诊断时刻(UTC)＋甲类 2h/乙类 24h，终点闭区间内提交为及时；迟报强制原因。</li>
46	 *   <li>去重：患者＋病种＋发病日期唯一有效卡（数据库唯一约束保证），重复返回已存在编号。</li>
47	 *   <li>幂等：requestId＋全字段指纹，同键同参重放首响，同键异参 409，不产生新版本。</li>
48	 *   <li>订正追加不可变版本；病种/病例类型变更重置为待审核，原初审结论作废留痕。</li>
49	 *   <li>初审通过与撤回并发，由条件 UPDATE 裁决唯一终态；撤回为终态。</li>
50	 *   <li>归档只读、重复归档幂等；订正一律拒绝，变更走双人不同审核员的特殊订正。</li>
51	 * </ul>
52	 */
53	@Service
54	public class EpidemicCardService {
55	
56	    private static final String SCOPE_SUBMIT = "SUBMIT";
57	    private static final String SCOPE_CORRECTION = "CORRECTION";
58	    private static final String SCOPE_SPECIAL = "SPECIAL";
59	
60	    private final CardRepository repository;
61	    private final ClockService clock;
62	    private final Fingerprinter fingerprinter;
63	
64	    public EpidemicCardService(CardRepository repository, ClockService clock, Fingerprinter fingerprinter) {
65	        this.repository = repository;
66	        this.clock = clock;
67	        this.fingerprinter = fingerprinter;
68	    }
69	
70	    // ---------------- 初报 ----------------
71	
72	    @Transactional
73	    public CardResponse submit(SubmitCardRequest request) {
74	        String fingerprint = fingerprinter.fingerprint(request);
75	        var existing = repository.findIdempotency(request.requestId(), SCOPE_SUBMIT);
76	        if (existing.isPresent()) {
77	            return replayOrConflict(existing.get(), fingerprint, CardResponse.class);
78	        }
79	
80	        DiseasePo disease = repository.findDisease(request.diseaseCode())
81	                .orElseThrow(() -> new BusinessRuleException("病种不存在: " + request.diseaseCode()));
82	        if (repository.findInstitution(request.institutionCode()).isEmpty()) {
83	            throw new BusinessRuleException("医疗机构不存在: " + request.institutionCode());
84	        }
85	
86	        Instant now = clock.now();
87	        Instant deadline = deadline(request.diagnosisTime(), disease.category());
88	        boolean late = isLate(now, deadline);
89	        if (late && isBlank(request.lateReason())) {
90	            throw new BusinessRuleException("已超过报告时限（迟报），必须填写迟报原因");
91	        }
92	
93	        String dedupKey = dedupKey(request.patientId(), request.diseaseCode(), request.onsetDate());
94	        var duplicate = repository.findCardByDedupKey(dedupKey);
95	        if (duplicate.isPresent()) {
96	            CardResponse response = toResponse(duplicate.get(),
97	                    repository.findLatestVersion(duplicate.get().getCardNo()).orElseThrow(), true);
98	            saveIdempotency(request.requestId(), SCOPE_SUBMIT, fingerprint,
99	                    duplicate.get().getCardNo(), duplicate.get().getCurrentVersion(), response, now);
100	            return response;
101	        }
102	
103	        CardPo card = new CardPo();
104	        card.setCardNo(newCardNo());
105	        card.setPatientId(request.patientId());
106	        card.setPatientName(request.patientName());
107	        card.setDiseaseCode(request.diseaseCode());
108	        card.setOnsetDate(request.onsetDate());
109	        card.setInstitutionCode(request.institutionCode());
110	        card.setCurrentVersion(1);
111	        card.setStatus(CardStatus.PENDING_REVIEW);
112	        card.setDedupKey(dedupKey);
113	        card.setCreatedAt(now);
114	        card.setUpdatedAt(now);
115	
116	        CardVersionPo version = new CardVersionPo(
117	                null, card.getCardNo(), 1, "INITIAL",
118	                disease.code(), disease.name(), disease.category().name(),
119	                request.caseType(), request.patientId(), request.patientName(),
120	                request.age(), request.gender(), request.onsetDate(), request.diagnosisTime(),
121	                request.institutionCode(), request.reporter(), request.address(), request.phone(),
122	                late, late ? request.lateReason() : null, request.requestId(), now);
123	
124	        try {
125	            repository.insertCard(card);
126	            repository.insertVersion(version);
127	            repository.insertTrail(card.getCardNo(), 1, AuditAction.SUBMIT, request.reporter(),
128	                    "初报提交" + (late ? "（迟报）" : ""), now);
129	        } catch (DuplicateKeyException e) {
130	            // 并发重复报告：唯一约束裁决，不新建卡片，返回已存在卡片。
131	            CardPo winner = repository.findCardByDedupKey(dedupKey)
132	                    .orElseThrow(() -> new BusinessRuleException("报告卡状态冲突，请重试"));
133	            CardResponse response = toResponse(winner,
134	                    repository.findLatestVersion(winner.getCardNo()).orElseThrow(), true);
135	            saveIdempotency(request.requestId(), SCOPE_SUBMIT, fingerprint,
136	                    winner.getCardNo(), winner.getCurrentVersion(), response, now);
137	            return response;
138	        }
139	
140	        CardResponse response = toResponse(card, version, false);
141	        saveIdempotency(request.requestId(), SCOPE_SUBMIT, fingerprint,
142	                card.getCardNo(), 1, response, now);
143	        return response;
144	    }
145	
146	    // ---------------- 订正 ----------------
147	
148	    @Transactional
149	    public CardResponse correct(CorrectCardRequest request) {
150	        // 先锁卡，串行化同卡订正/审核/撤回，再判定幂等与状态。
151	        CardPo card = repository.findCardForUpdate(request.cardNo())
152	                .orElseThrow(() -> new NotFoundException("报告卡不存在: " + request.cardNo()));
153	
154	        String fingerprint = fingerprinter.fingerprint(request);
155	        var existing = repository.findIdempotency(request.requestId(), SCOPE_CORRECTION);
156	        if (existing.isPresent()) {
157	            return replayOrConflict(existing.get(), fingerprint, CardResponse.class);
158	        }
159	
160	        if (card.getStatus() == CardStatus.ARCHIVED) {
161	            throw new BusinessRuleException("卡片已终审归档（只读），订正请求拒绝；疫情核实确需变更请走特殊订正流程");
162	        }
163	        if (card.getStatus() == CardStatus.WITHDRAWN) {
164	            throw new BusinessRuleException("卡片已撤回（终态），不可订正");
165	        }
166	
167	        CardVersionPo latest = repository.findLatestVersionForUpdate(request.cardNo())
168	                .orElseThrow(() -> new IllegalStateException("卡片缺少版本数据: " + request.cardNo()));
169	
170	        String newDiseaseCode = request.diseaseCode() != null ? request.diseaseCode() : latest.diseaseCode();
171	        DiseasePo disease = repository.findDisease(newDiseaseCode)
172	                .orElseThrow(() -> new BusinessRuleException("病种不存在: " + newDiseaseCode));
173	        String newInstitution = request.institutionCode() != null
174	                ? request.institutionCode() : latest.institutionCode();
175	        if (repository.findInstitution(newInstitution).isEmpty()) {
176	            throw new BusinessRuleException("医疗机构不存在: " + newInstitution);
177	        }
178	        String newCaseType = request.caseType() != null ? request.caseType() : latest.caseType();
179	        LocalDate newOnsetDate = request.onsetDate() != null ? request.onsetDate() : latest.onsetDate();
180	        Instant newDiagnosisTime = request.diagnosisTime() != null
181	                ? request.diagnosisTime() : latest.diagnosisTime();
182	
183	        Instant now = clock.now();
184	        Instant deadline = deadline(newDiagnosisTime, disease.category());
185	        boolean late = isLate(now, deadline);
186	        if (late && isBlank(request.lateReason())) {
187	            throw new BusinessRuleException("订正后版本已超过报告时限（迟报），必须填写迟报原因");
188	        }
189	
190	        boolean diseaseChanged = !newDiseaseCode.equals(latest.diseaseCode())
191	                || !newCaseType.equals(latest.caseType());
192	        int newVersionNo = latest.versionNo() + 1;
193	
194	        CardVersionPo next = new CardVersionPo(
195	                null, card.getCardNo(), newVersionNo, "CORRECTION",
196	                disease.code(), disease.name(), disease.category().name(),
197	                newCaseType, latest.patientId(),
198	                request.patientName() != null ? request.patientName() : latest.patientName(),
199	                request.age() != null ? request.age() : latest.age(),
200	                request.gender() != null ? request.gender() : latest.gender(),
201	                newOnsetDate, newDiagnosisTime, newInstitution,
202	                request.reporter() != null ? request.reporter() : latest.reporter(),
203	                request.address() != null ? request.address() : latest.address(),
204	                request.phone() != null ? request.phone() : latest.phone(),
205	                late, late ? request.lateReason() : null,
206	                request.requestId(), now);
207	
208	        String newDedupKey = dedupKey(next.patientId(), newDiseaseCode, newOnsetDate);
209	        try {
210	            repository.insertVersion(next);
211	            if (diseaseChanged) {
212	                int rows = repository.compareAndUpdateCard(card.getCardNo(), card.getStatus(),
213	                        CardStatus.PENDING_REVIEW, newVersionNo, newDiseaseCode, newDedupKey, now);
214	                if (rows == 0) {
215	                    throw new BusinessRuleException("卡片状态已被并发改变，订正失败");
216	                }
217	            } else {
218	                int rows = repository.compareAndUpdateCard(card.getCardNo(), card.getStatus(),
219	                        card.getStatus(), newVersionNo,
220	                        newDiseaseCode.equals(latest.diseaseCode()) ? null : newDiseaseCode,
221	                        newDedupKey.equals(card.getDedupKey()) ? null : newDedupKey, now);
222	                if (rows == 0) {
223	                    throw new BusinessRuleException("卡片状态已被并发改变，订正失败");
224	                }
225	            }
226	        } catch (DuplicateKeyException e) {
227	            throw new BusinessRuleException("订正后的患者＋病种＋发病日期与其他有效卡重复，拒绝订正");
228	        }
229	
230	        repository.insertTrail(card.getCardNo(), newVersionNo, AuditAction.CORRECTED,
231	                next.reporter(), "订正生成版本 " + newVersionNo
232	                        + (diseaseChanged ? "；病种/病例类型变更，重新起算审核" : ""), now);
233	        if (diseaseChanged && card.getStatus() == CardStatus.PENDING_FINAL) {
234	            String priorReviewer = repository.findTrails(card.getCardNo()).stream()
235	                    .filter(t -> t.action() == AuditAction.REVIEW_APPROVED)
236	                    .reduce((first, second2) -> second2)
237	                    .map(AuditTrailPo::operator)
238	                    .orElse("原审核员");
239	            repository.insertTrail(card.getCardNo(), latest.versionNo(), AuditAction.REVIEW_VOIDED,
240	                    next.reporter(), "病种/病例类型变更，原初审通过结论作废（原审核员：" + priorReviewer + "）", now);
241	        }
242	
243	        card.setStatus(diseaseChanged ? CardStatus.PENDING_REVIEW : card.getStatus());
244	        card.setCurrentVersion(newVersionNo);
245	        card.setDiseaseCode(newDiseaseCode);
246	        CardResponse response = toResponse(card, next, false);
247	        saveIdempotency(request.requestId(), SCOPE_CORRECTION, fingerprint,
248	                card.getCardNo(), newVersionNo, response, now);
249	        return response;
250	    }
251	
252	    // ---------------- 初审 / 撤回 / 终审 ----------------
253	
254	    @Transactional
255	    public ActionResponse review(String cardNo, ReviewRequest request) {
256	        CardPo card = repository.findCardForUpdate(cardNo)
257	                .orElseThrow(() -> new NotFoundException("报告卡不存在: " + cardNo));
258	        if (card.getStatus() != CardStatus.PENDING_REVIEW) {
259	            throw new BusinessRuleException("当前状态[" + card.getStatus() + "]不允许初审；仅待审核卡片可初审");
260	        }
261	        int versionNo = card.getCurrentVersion();
262	        int rows = repository.compareAndUpdateCard(cardNo, CardStatus.PENDING_REVIEW,
263	                CardStatus.PENDING_FINAL, null, null, null, clock.now());
264	        if (rows == 0) {
265	            throw new BusinessRuleException("卡片已被并发撤回或状态变更，初审未生效");
266	        }
267	        repository.insertTrail(cardNo, versionNo, AuditAction.REVIEW_APPROVED, request.reviewer(),
268	                isBlank(request.comment()) ? "初审通过" : request.comment(), clock.now());
269	        return new ActionResponse(cardNo, CardStatus.PENDING_FINAL, "初审通过，进入待终审");
270	    }
271	
272	    @Transactional
273	    public ActionResponse withdraw(String cardNo, WithdrawRequest request) {
274	        CardPo card = repository.findCardForUpdate(cardNo)
275	                .orElseThrow(() -> new NotFoundException("报告卡不存在: " + cardNo));
276	        if (card.getStatus() != CardStatus.PENDING_REVIEW) {
277	            throw new BusinessRuleException("当前状态[" + card.getStatus() + "]不允许撤回；仅审核通过前可撤回");
278	        }
279	        Instant now = clock.now();
280	        int rows = repository.withdrawCard(cardNo, now);
281	        if (rows == 0) {
282	            throw new BusinessRuleException("卡片已被并发初审通过，撤回未生效（唯一终态）");
283	        }
284	        repository.insertTrail(cardNo, card.getCurrentVersion(), AuditAction.WITHDRAWN,
285	                request.operator(), isBlank(request.reason()) ? "审核通过前撤回（终态）" : request.reason(), now);
286	        return new ActionResponse(cardNo, CardStatus.WITHDRAWN, "卡片已撤回，终态不可恢复");
287	    }
288	
289	    @Transactional
290	    public ActionResponse archive(String cardNo, ArchiveRequest request) {
291	        CardPo card = repository.findCardForUpdate(cardNo)
292	                .orElseThrow(() -> new NotFoundException("报告卡不存在: " + cardNo));
293	        if (card.getStatus() == CardStatus.ARCHIVED) {
294	            return new ActionResponse(cardNo, CardStatus.ARCHIVED, "卡片已归档，重复归档幂等成功");
295	        }
296	        if (card.getStatus() != CardStatus.PENDING_FINAL) {
297	            throw new BusinessRuleException("当前状态[" + card.getStatus() + "]不允许终审归档；仅初审通过卡片可归档");
298	        }
299	        Instant now = clock.now();
300	        int rows = repository.compareAndUpdateCard(cardNo, CardStatus.PENDING_FINAL,
301	                CardStatus.ARCHIVED, null, null, null, now);
302	        if (rows == 0) {
303	            throw new BusinessRuleException("卡片状态已被并发改变，归档未生效");
304	        }
305	        repository.insertTrail(cardNo, card.getCurrentVersion(), AuditAction.ARCHIVED,
306	                request.reviewer(), isBlank(request.comment()) ? "终审通过，归档（只读）" : request.comment(), now);
307	        return new ActionResponse(cardNo, CardStatus.ARCHIVED, "终审通过，卡片归档只读");
308	    }
309	
310	    // ---------------- 特殊订正（双人） ----------------
311	
312	    @Transactional
313	    public SpecialCorrectionResponse startSpecial(SpecialCorrectRequest request) {
314	        String fingerprint = fingerprinter.fingerprint(request);
315	        var existing = repository.findIdempotency(request.requestId(), SCOPE_SPECIAL);
316	        if (existing.isPresent()) {
317	            return replayOrConflict(existing.get(), fingerprint, SpecialCorrectionResponse.class);
318	        }
319	
320	        CardPo card = repository.findCardForUpdate(request.cardNo())
321	                .orElseThrow(() -> new NotFoundException("报告卡不存在: " + request.cardNo()));
322	        if (card.getStatus() != CardStatus.ARCHIVED) {
323	            throw new BusinessRuleException("仅已归档卡片可发起特殊订正；当前状态[" + card.getStatus() + "]");
324	        }
325	        if (request.diseaseCode() != null && repository.findDisease(request.diseaseCode()).isEmpty()) {
326	            throw new BusinessRuleException("病种不存在: " + request.diseaseCode());
327	        }
328	
329	        Instant now = clock.now();
330	        SpecialCorrectionPo po = new SpecialCorrectionPo();
331	        po.setCardNo(request.cardNo());
332	        po.setRequestId(request.requestId());
333	        po.setDiseaseCode(request.diseaseCode());
334	        po.setCaseType(request.caseType());
335	        po.setDiagnosisTime(request.diagnosisTime());
336	        po.setReason(request.reason());
337	        po.setInitiator(request.initiator());
338	        po.setStatus(SpecialStatus.WAITING_SECOND);
339	        po.setCreatedAt(now);
340	
341	        long id;
342	        try {
343	            id = repository.insertSpecial(po);
344	        } catch (DuplicateKeyException e) {
345	            SpecialCorrectionPo winner = repository.findSpecialByRequestId(request.requestId())
346	                    .orElseThrow(() -> new BusinessRuleException("特殊订正请求冲突，请重试"));
347	            return toSpecialResponse(winner);
348	        }
349	        repository.insertTrail(request.cardNo(), card.getCurrentVersion(),
350	                AuditAction.SPECIAL_STARTED, request.initiator(),
351	                "归档后疫情核实发起特殊订正，等待两名不同审核员确认：" + request.reason(), now);
352	
353	        SpecialCorrectionPo saved = repository.findSpecialForUpdate(id).orElseThrow();
354	        SpecialCorrectionResponse response = toSpecialResponse(saved);
355	        saveIdempotency(request.requestId(), SCOPE_SPECIAL, fingerprint,
356	                request.cardNo(), card.getCurrentVersion(), response, now);
357	        return response;
358	    }
359	
360	    @Transactional
361	    public SpecialCorrectionResponse confirmSpecial(SpecialConfirmRequest request) {
362	        long specialId = request.specialId();
363	        String reviewer = request.reviewer();
364	        SpecialCorrectionPo special = repository.findSpecialForUpdate(specialId)
365	                .orElseThrow(() -> new NotFoundException("特殊订正流程不存在: " + specialId));
366	        if (special.getStatus() == SpecialStatus.EFFECTIVE) {
367	            return toSpecialResponse(special);
368	        }
369	
370	        Instant now = clock.now();
371	        if (special.getFirstReviewer() == null) {
372	            int rows = repository.updateSpecialFirst(special.getId(), reviewer, now);
373	            if (rows == 0) {
374	                special = repository.findSpecialForUpdate(specialId).orElseThrow();
375	                return toSpecialResponse(special);
376	            }
377	            repository.insertTrail(special.getCardNo(),
378	                    currentVersionOf(special.getCardNo()),
379	                    AuditAction.SPECIAL_FIRST_CONFIRMED, reviewer,
380	                    "特殊订正第一名审核员确认，尚需另一名审核员确认", now);
381	            special.setFirstReviewer(reviewer);
382	            special.setFirstAt(now);
383	            return toSpecialResponse(special);
384	        }
385	
386	        if (special.getFirstReviewer().equals(reviewer)) {
387	            throw new BusinessRuleException("特殊订正须两名不同审核员先后确认；第二名审核员不能与第一人相同");
388	        }
389	
390	        // 第二名不同审核员确认：锁定卡片并生效新版本（卡片保持 ARCHIVED 只读终态）。
391	        CardPo card = repository.findCardForUpdate(special.getCardNo()).orElseThrow();
392	        if (card.getStatus() != CardStatus.ARCHIVED) {
393	            throw new BusinessRuleException("卡片状态异常，特殊订正无法生效");
394	        }
395	        CardVersionPo latest = repository.findLatestVersionForUpdate(card.getCardNo()).orElseThrow();
396	
397	        String newDiseaseCode = special.getDiseaseCode() != null
398	                ? special.getDiseaseCode() : latest.diseaseCode();
399	        DiseasePo disease = repository.findDisease(newDiseaseCode)
400	                .orElseThrow(() -> new BusinessRuleException("病种不存在: " + newDiseaseCode));
401	        String newCaseType = special.getCaseType() != null ? special.getCaseType() : latest.caseType();
402	        Instant newDiagnosisTime = special.getDiagnosisTime() != null
403	                ? special.getDiagnosisTime() : latest.diagnosisTime();
404	        int newVersionNo = latest.versionNo() + 1;
405	
406	        CardVersionPo next = new CardVersionPo(
407	                null, card.getCardNo(), newVersionNo, "SPECIAL",
408	                disease.code(), disease.name(), disease.category().name(),
409	                newCaseType, latest.patientId(), latest.patientName(), latest.age(), latest.gender(),
410	                latest.onsetDate(), newDiagnosisTime, latest.institutionCode(), latest.reporter(),
411	                latest.address(), latest.phone(),
412	                // 特殊订正为归档后疫情核实更正，迟报属性沿用作废前最新版本判定，不重新起算报告时限。
413	                latest.late(), latest.lateReason(),
414	                special.getRequestId(), now);
415	
416	        String newDedupKey = dedupKey(next.patientId(), newDiseaseCode, next.onsetDate());
417	        repository.insertVersion(next);
418	        int cardRows;
419	        try {
420	            cardRows = repository.updateCardVersionInfo(card.getCardNo(), newVersionNo,
421	                    newDiseaseCode, newDedupKey, now);
422	        } catch (DuplicateKeyException e) {
423	            throw new BusinessRuleException("特殊订正后的患者＋病种＋发病日期与其他有效卡重复，订正拒绝");
424	        }
425	        if (cardRows == 0) {
426	            throw new BusinessRuleException("卡片已非归档状态，特殊订正生效失败");
427	        }
428	        int specialRows = repository.updateSpecialEffective(special.getId(), reviewer,
429	                now, newVersionNo);
430	        if (specialRows == 0) {
431	            throw new BusinessRuleException("特殊订正流程已被并发处理");
432	        }
433	        repository.insertTrail(card.getCardNo(), newVersionNo,
434	                AuditAction.SPECIAL_SECOND_CONFIRMED, reviewer,
435	                "第二名（不同）审核员确认，特殊订正生效，生成版本 " + newVersionNo
436	                        + "；核实结论：" + special.getReason(), now);
437	
438	        special.setSecondReviewer(reviewer);
439	        special.setSecondAt(now);
440	        special.setStatus(SpecialStatus.EFFECTIVE);
441	        special.setEffectiveVersion(newVersionNo);
442	        return toSpecialResponse(special);
443	    }
444	
445	    // ---------------- 查询 ----------------
446	
447	    @Transactional(readOnly = true)
448	    public CardResponse getCard(String cardNo) {
449	        CardPo card = repository.findCard(cardNo)
450	                .orElseThrow(() -> new NotFoundException("报告卡不存在: " + cardNo));
451	        CardVersionPo latest = repository.findLatestVersion(cardNo)
452	                .orElseThrow(() -> new IllegalStateException("卡片缺少版本数据: " + cardNo));
453	        return toResponse(card, latest, false);
454	    }
455	
456	    @Transactional(readOnly = true)
457	    public List<AuditTrailResponse> getTrails(String cardNo) {
458	        if (repository.findCard(cardNo).isEmpty()) {
459	            throw new NotFoundException("报告卡不存在: " + cardNo);
460	        }
461	        return repository.findTrails(cardNo).stream()
462	                .map(t -> new AuditTrailResponse(t.versionNo(), t.action(), t.operator(),
463	                        t.detail(), t.createdAt()))
464	                .toList();
465	    }
466	
467	    @Transactional(readOnly = true)
468	    public List<CardVersionResponse> getVersions(String cardNo) {
469	        if (repository.findCard(cardNo).isEmpty()) {
470	            throw new NotFoundException("报告卡不存在: " + cardNo);
471	        }
472	        return repository.findVersions(cardNo).stream()
473	                .map(v -> new CardVersionResponse(v.versionNo(), v.changeType(), v.diseaseCode(),
474	                        v.diseaseName(), v.category(), v.caseType(), v.patientName(),
475	                        v.onsetDate(), v.diagnosisTime(), v.late(), v.lateReason(),
476	                        v.requestId(), v.submittedAt()))
477	                .toList();
478	    }
479	
480	    // ---------------- 内部辅助 ----------------
481	
482	    private int currentVersionOf(String cardNo) {
483	        return repository.findCard(cardNo).map(CardPo::getCurrentVersion).orElse(0);
484	    }
485	
486	    private <T> T replayOrConflict(IdempotencyPo record, String fingerprint, Class<T> type) {
487	        if (!record.fingerprint().equals(fingerprint)) {
488	            throw new IdempotencyConflictException(
489	                    "requestId=" + record.requestId() + " 已用于不同参数的请求（409 冲突），本次请求被拒绝且不产生新版本");
490	        }
491	        return fingerprinter.fromJson(record.responseJson(), type);
492	    }
493	
494	    private void saveIdempotency(String requestId, String scope, String fingerprint, String cardNo,
495	                                 Integer versionNo, Object response, Instant now) {
496	        try {
497	            repository.insertIdempotency(new IdempotencyPo(requestId, scope, fingerprint, cardNo,
498	                    versionNo, fingerprinter.toJson(response), now));
499	        } catch (DuplicateKeyException e) {
500	            // 并发同键请求已由另一事务落库：以库中首次结果为准。
501	            var saved = repository.findIdempotency(requestId, scope);
502	            if (saved.isPresent() && saved.get().fingerprint().equals(fingerprint)) {
503	                return;
504	            }
505	            throw new IdempotencyConflictException("requestId=" + requestId + " 并发请求参数不一致（409 冲突）");
506	        }
507	    }
508	
509	    private CardResponse toResponse(CardPo card, CardVersionPo v, boolean duplicate) {
510	        return new CardResponse(
511	                duplicate,
512	                card.getCardNo(),
513	                v.versionNo(),
514	                card.getStatus(),
515	                v.diseaseCode(),
516	                v.diseaseName(),
517	                v.category(),
518	                v.caseType(),
519	                v.patientId(),
520	                v.patientName(),
521	                v.age(),
522	                v.gender(),
523	                v.onsetDate(),
524	                v.diagnosisTime(),
525	                v.institutionCode(),
526	                v.reporter(),
527	                v.address(),
528	                v.phone(),
529	                v.late(),
530	                v.lateReason(),
531	                deadline(v.diagnosisTime(), DiseaseCategory.valueOf(v.category())),
532	                v.submittedAt(),
533	                card.getUpdatedAt());
534	    }
535	
536	    private SpecialCorrectionResponse toSpecialResponse(SpecialCorrectionPo po) {
537	        return new SpecialCorrectionResponse(
538	                po.getId(), po.getCardNo(), po.getStatus(),
539	                po.getFirstReviewer(), po.getFirstAt(),
540	                po.getSecondReviewer(), po.getSecondAt(),
541	                po.getEffectiveVersion(), po.getReason());
542	    }
543	
544	    /** 报告时限终点（含端点）：诊断时刻＋分类时限。 */
545	    private Instant deadline(Instant diagnosisTime, DiseaseCategory category) {
546	        return diagnosisTime.plus(Duration.ofHours(category.deadlineHours()));
547	    }
548	
549	    /** 迟报判定：提交时刻严格晚于时限终点为迟报；恰在终点为及时。 */
550	    private boolean isLate(Instant submittedAt, Instant deadline) {
551	        return submittedAt.isAfter(deadline);
552	    }
553	
554	    /** 有效卡去重指纹：患者＋病种＋发病日期。 */
555	    private String dedupKey(String patientId, String diseaseCode, LocalDate onsetDate) {
556	        String raw = patientId + "|" + diseaseCode + "|" + onsetDate;
557	        try {
558	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
559	            return HexFormat.of().formatHex(digest.digest(raw.getBytes(StandardCharsets.UTF_8)));
560	        } catch (NoSuchAlgorithmException e) {
561	            throw new IllegalStateException(e);
562	        }
563	    }
564	
565	    private String newCardNo() {
566	        return "C" + Long.toHexString(clock.now().toEpochMilli())
567	                + UUID.randomUUID().toString().substring(0, 8);
568	    }
569	
570	    private boolean isBlank(String value) {
571	        return value == null || value.isBlank();
572	    }
573	}
