2	
3	import com.example.starter.epidemic.api.CardResponse;
4	import com.example.starter.epidemic.api.ReviewRequest;
5	import com.example.starter.epidemic.api.SubmitCardRequest;
6	import com.example.starter.epidemic.api.WithdrawRequest;
